/// The name stored by the record at `off`.
fn nameAt(off: usize) []const u8 {
    return blob[off + 1 ..][0 .. blob[off] & 0x1f];
}

/// The 1-2 codepoints a record's UTF-8 `value` stands for. The second is 0
/// when the entity names a single codepoint, which 2032 of the 2125 do.
fn decodeValue(value: []const u8) [2]u32 {
    var cps: [2]u32 = .{ 0, 0 };
    var i: usize = 0;
    var n: usize = 0;
    while (i < value.len and n < 2) : (n += 1) {
        const b = value[i];
        if (b < 0x80) {
            cps[n] = b;
            i += 1;
        } else if (b < 0xe0) {
            cps[n] = (@as(u32, b & 0x1f) << 6) | cont(value[i + 1]);
            i += 2;
        } else if (b < 0xf0) {
            cps[n] = (@as(u32, b & 0x0f) << 12) |
                (cont(value[i + 1]) << 6) | cont(value[i + 2]);
            i += 3;
        } else {
            cps[n] = (@as(u32, b & 0x07) << 18) |
                (cont(value[i + 1]) << 12) | (cont(value[i + 2]) << 6) |
                cont(value[i + 3]);
            i += 4;
        }
    }
    return cps;
}

/// The six payload bits of a UTF-8 continuation byte.
fn cont(b: u8) u32 {
    return b & 0x3f;
}

/// Look up a named HTML entity. `name` is the whole reference including its
/// '&' and ';', the way the parser reports an `.entity` substring; the 1-2
/// codepoints it stands for come back with a 0 second element for the
/// single-codepoint majority. `null` means the name is not in the table, and
/// every caller then emits the reference verbatim.
pub fn entity_lookup(name: []const u8) ?[2]u32 {
    // Shortest possible reference is `&ab;`: every stored name is at least
    // two characters, as `md_is_named_entity_contents` also requires.
    if (name.len < 4 or name[0] != '&' or name[name.len - 1] != ';') return null;
    const key = name[1 .. name.len - 1];
    if (key.len > max_name_len) return null;

    // Narrow to the one window that can hold `key`: the last checkpoint whose
    // name does not sort after it.
    var lo: usize = 0;
    var hi: usize = index.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        if (std.mem.order(u8, nameAt(index[mid]), key) == .gt) {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }
    if (lo == 0) return null;

    var off: usize = index[lo - 1];
    const end: usize = if (lo < index.len) index[lo] else blob.len;
    while (off < end) {
        const name_len: usize = blob[off] & 0x1f;
        const value_len: usize = (blob[off] >> 5) + 1;
        switch (std.mem.order(u8, blob[off + 1 ..][0..name_len], key)) {
            .eq => return decodeValue(blob[off + 1 + name_len ..][0..value_len]),
            // The window is sorted, so no record after this one can match.
            .gt => return null,
            .lt => off += 1 + name_len + value_len,
        }
    }
    return null;
}

const testing = std.testing;

// The .txt suites reach only a handful of these names, so nothing else pins
// the invariants the lookup rests on: that the blob is sorted and gap-free,
// and that every checkpoint lands on a record boundary. A generator bug in
// any of the three would silently lose entities in the middle of the table.
test "every record is well-formed, sorted and findable" {
    var buf: [max_name_len + 2]u8 = undefined;
    var prev: []const u8 = "";
    var off: usize = 0;
    var n: usize = 0;
    while (off < blob.len) : (n += 1) {
        const name_len: usize = blob[off] & 0x1f;
        const value_len: usize = (blob[off] >> 5) + 1;
        const name = blob[off + 1 ..][0..name_len];
        try testing.expect(std.mem.order(u8, prev, name) == .lt);
        if (n % stride == 0) try testing.expectEqual(off, index[n / stride]);
        const ref = try std.fmt.bufPrint(&buf, "&{s};", .{name});
        try testing.expectEqual(
            decodeValue(blob[off + 1 + name_len ..][0..value_len]),
            entity_lookup(ref).?,
        );
        prev = name;
        off += 1 + name_len + value_len;
    }
    try testing.expectEqual(count, n);
    try testing.expectEqual(index.len, (count + stride - 1) / stride);
}

test "a name that is not in the table resolves to null" {
    // Neither a prefix nor an extension of a stored name may match, and the
    // comparison is case-sensitive: `&Amp;` is not `&amp;`.
    for ([_][]const u8{
        "", "&", "&;", "&a;", "amp;", "&amp", "&am;", "&Amp;", "&ampx;", "&zzz;",
        "&" ++ "a" ** 48 ++ ";",
    }) |name| {
        try testing.expect(entity_lookup(name) == null);
    }
}

test "a stored name resolves to the codepoints it stands for" {
    try testing.expectEqual([2]u32{ 0x26, 0x0 }, entity_lookup("&amp;").?);
    try testing.expectEqual([2]u32{ 0x1d504, 0x0 }, entity_lookup("&Afr;").?);
    try testing.expectEqual([2]u32{ 0x3d, 0x20e5 }, entity_lookup("&bne;").?);
    try testing.expectEqual([2]u32{ 0xa, 0x0 }, entity_lookup("&NewLine;").?);
}
